【题 9.114】运行以下程序时，从键盘输入 6，则下面程序的运行结果是【 】。

```c
#include <stdio.h>
void fun(char  * a,char b);
int main( )
{   char s[ ]="97531",c;
    c=getchar();
    fun(s,c);
    puts(s);
    return(0);
}
void fun(char  * a,char b)
{   while( * (a++)!='\0');
    while( * (a-1)<b)   * (a--)= * (a-1);
    * (a--)=b;
}
```

