int fun(char  * p, char  * q)
{   int i;
    char  * p1=p, * q1;
    for( i=0 ;  * p!='\0'; p++, i++)
    {   p=p1+i;
        if( * p!= * q)   continue;
        for( q1=q+1, p=p+1;  * p!='\0' &&  * q1!='\0'; q1++, p++)
            if( * p!= * q1)   break;
        if( * q1=='\0')   return i;
    }
    return (-1);
}

