#include <stdio.h>

/* 把 src 中第 m 个字符开始的全部字符复制到 dst（m 为 1 基；越界时得到空串） */
void copy_from(char *dst, char *src, int m)
{
    char *p = src;
    char *q = dst;
    int i;

    for (i = 1; i < m && *p != '\0'; i++)
        p = p + 1;

    while (*p != '\0') {
        *q = *p;
        q = q + 1;
        p = p + 1;
    }
    *q = '\0';
}

int main(void)
{
    char s[80], t[80];
    int m;

    if (scanf("%79s %d", s, &m) != 2)
        return 1;

    copy_from(t, s, m);
    printf("%s\n", t);

    return 0;
}

